import math
import tempfile
import unittest
from pathlib import Path

import gcode_analysis as ga


def orca_like(body: str, config: str = "") -> str:
    return (
        "; HEADER_BLOCK_START\n; generated by OrcaSlicer 2.4.2 on 2026-09-11 at 20:05:36\n; HEADER_BLOCK_END\n"
        "; EXECUTABLE_BLOCK_START\n;TYPE:Custom\nM140 S60\nM104 S140\nG90\nM83\nG28\nM190 S60\nM109 S210\n"
        "G1 X0 Y-1.2 F20000\nG1 Z0.3\nG1 X0 E10\nG1 Y98.8 E7.9\n"  # purge line along the bed edge
        f"{body}"
        ";TYPE:Custom\nM400\nM140 S0\nM104 S0\nG1 X202 Y264.5 F20000\nM84\n; EXECUTABLE_BLOCK_END\n"
        "; filament used [mm] = 100.00\n; total filament used [g] = 0.30\n"
        "; estimated printing time (normal mode) = 5m 0s\n"
        "; CONFIG_BLOCK_START\n; printer_model = Elegoo Centauri Carbon\n; nozzle_diameter = 0.4\n"
        "; filament_type = PLA\n; curr_bed_type = Textured PEI Plate\n; filament_settings_id = \"Elegoo PLA @ECC\"\n"
        f"{config}; CONFIG_BLOCK_END\n"
    )


TWO_LAYERS = (
    ";LAYER_CHANGE\n;Z:0.2\n;HEIGHT:0.2\nG1 X100 Y100 Z0.2 F30000\n;TYPE:Outer wall\n"
    "G1 X120 Y100 E1\nG1 X120 Y120 E1\nG1 X100 Y120 E1\nG1 X100 Y100 E1\n"
    "G1 E-0.8\nG1 X110 Y110 F30000\nG1 E0.8\n"
    ";TYPE:Sparse infill\nG1 X115 Y110 E0.2\n"
    ";LAYER_CHANGE\n;Z:0.4\n;HEIGHT:0.2\nG1 Z0.4\nG1 X120 Y110\n;TYPE:Outer wall\n"
    "G2 X130 Y120 I10 J0 E1.5\n"  # clockwise quarter circle from (120,110) around (130,110) → bulges to x=120..130, y up to 120
)


class GcodeAnalysisTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.dir = Path(self._tmp.name)

    def tearDown(self):
        self._tmp.cleanup()

    def analyze(self, text: str):
        path = self.dir / "part.gcode"
        path.write_text(text)
        return ga.analyze(path)

    def test_layers_bounds_features_and_settings(self):
        analysis, toolpath = self.analyze(orca_like(TWO_LAYERS))

        self.assertEqual([l["z"] for l in analysis["layers"]], [0.2, 0.4])
        self.assertEqual(analysis["bounds"]["model"], {"min": [100, 100, 0.2], "max": [130, 120, 0.4]})
        self.assertLess(analysis["bounds"]["travel"]["min"][1], 0)   # purge line counts only as travel
        self.assertGreater(analysis["bounds"]["travel"]["max"][1], 256)
        self.assertEqual(analysis["features"], ["Unknown", "Custom", "Outer wall", "Sparse infill"])
        self.assertEqual(analysis["config"]["printer_model"], "Elegoo Centauri Carbon")
        self.assertEqual(analysis["config"]["filament_settings_id"], "Elegoo PLA @ECC")
        self.assertEqual(analysis["slicer"], "OrcaSlicer 2.4.2")
        self.assertEqual(analysis["estimates"]["estimate_s"], 300)
        self.assertEqual(analysis["temperatures"]["nozzle"]["max"], 210)
        self.assertEqual(analysis["temperatures"]["bed"]["values"], [0, 60])
        self.assertEqual(analysis["stats"]["retractions"], 1)
        self.assertEqual(analysis["stats"]["arcs"], 1)
        self.assertEqual(analysis["findings"], [])
        self.assertEqual(analysis["unknown_commands"], {})

    def test_toolpath_round_trips_per_layer(self):
        analysis, toolpath = self.analyze(orca_like(TWO_LAYERS))
        first, second = analysis["layers"]

        paths = ga.decode_toolpath(toolpath, first["offset"], first["length"])
        wall = analysis["features"].index("Outer wall")
        self.assertEqual(paths[0], (wall, [(100, 100), (120, 100), (120, 120), (100, 120), (100, 100)]))
        self.assertEqual(paths[1][1], [(110, 110), (115, 110)])

        arc = ga.decode_toolpath(toolpath, second["offset"], second["length"])[0][1]
        self.assertEqual((arc[0], arc[-1]), ((120, 110), (130, 120)))
        for px, py in arc:  # every sampled point lies on the 10 mm circle around (130, 110)
            self.assertAlmostEqual(math.hypot(px - 130, py - 110), 10, delta=0.02)
        self.assertLessEqual(max(py for _, py in arc), 120.01)

    def test_occupancy_grid_marks_printed_cells_only(self):
        analysis, _ = self.analyze(orca_like(TWO_LAYERS))
        self.assertGreater(ga.grid_cells_in(analysis, 99, 99, 101, 101), 0)
        self.assertEqual(ga.grid_cells_in(analysis, 246, 0, 256, 20), 0)   # CC purge/wipe zone
        self.assertEqual(ga.grid_cells_in(analysis, -1, -2, 1, 99), 0)    # the purge line is start G-code

    def test_dangerous_and_unexpected_commands_are_reported(self):
        body = ("M500\nM84\n" + TWO_LAYERS + "G28\nM221 S300\nFANCY_MACRO\nFANCY_MACRO X=1\n"
                ";TYPE:Outer wall\nG1 X101 Y101 E0.1\n")
        analysis, _ = self.analyze(orca_like(body))

        found = {(f["command"], f["level"]) for f in analysis["findings"]}
        self.assertIn(("M500", "fail"), found)
        self.assertIn(("M84", "fail"), found)       # motors off before the last extrusion
        self.assertIn(("G28", "warn"), found)       # homing after printing began
        self.assertIn(("M221", "warn"), found)
        self.assertEqual(analysis["unknown_commands"], {"FANCY_MACRO": 2})
        self.assertNotIn(("M84", "fail"), {(f["command"], f["level"]) for f in self.analyze(orca_like(TWO_LAYERS))[0]["findings"]})

    def test_files_without_layer_markers_split_layers_on_z(self):
        body = ("G90\nM82\nG92 E0\nG1 X10 Y10 Z0.3 F3000\nG1 X20 Y10 E1\nG1 Z0.6\nG1 X10 Y10 E2\n")
        analysis, _ = self.analyze(body)
        self.assertEqual([l["z"] for l in analysis["layers"]], [0.3, 0.6])
        self.assertEqual(analysis["stats"]["extruded_mm"], 2)

    def test_real_orcaslicer_output_has_no_findings(self):
        sample = next(iter(sorted(Path(tempfile.gettempdir()).glob(
            "claude/*/*/scratchpad/orca-smoke/out-textured/plate_1.gcode"))), None)
        if sample is None:
            self.skipTest("no OrcaSlicer sample G-code on this machine")
        analysis, toolpath = ga.analyze(sample)
        self.assertEqual(len(analysis["layers"]), 100)
        self.assertEqual((analysis["findings"], analysis["unknown_commands"]), ([], {}))
        low, high = analysis["bounds"]["model"]["min"], analysis["bounds"]["model"]["max"]
        self.assertTrue(0 < low[0] < high[0] < 256 and 0 < low[1] < high[1] < 256)
        self.assertAlmostEqual(high[0] - low[0], 20.5, delta=1.0)
        self.assertEqual(analysis["config"]["curr_bed_type"], "Textured PEI Plate")
        self.assertGreater(len(toolpath), 1000)


if __name__ == "__main__":
    unittest.main()
